import{_ as t}from"./chunks/image34.Dh8mAVwC.js";import{_ as o}from"./chunks/image35.DB3Pfc49.js";import{_ as a}from"./chunks/image27.BxJp-sZ3.js";import{_ as n}from"./chunks/2.BRgDBKom.js";import{_ as i,o as r,c as s,am as l}from"./chunks/framework.CenUaW7a.js";const c="/projects/AiMechaM1/en/advanced-kit/assets/4.Dkz19y7S.webp",d="/projects/AiMechaM1/en/advanced-kit/assets/image33.-65MGXbF.png",p="/projects/AiMechaM1/en/advanced-kit/assets/image38.Bcw9Lqb4.png",h="/projects/AiMechaM1/en/advanced-kit/assets/image36.OTJ9Ir7M.png",m="/projects/AiMechaM1/en/advanced-kit/assets/image37.Cde6fs5i.png",M=JSON.parse('{"title":"3.4 Lesson 4: Translational Motion and Timed Control","description":"","frontmatter":{},"headers":[],"relativePath":"docs/3. Course materials/3.4 Lesson 4 Translational Motion and Timed Control.md","filePath":"docs/3. Course materials/3.4 Lesson 4 Translational Motion and Timed Control.md"}'),g={name:"docs/3. Course materials/3.4 Lesson 4 Translational Motion and Timed Control.md"};function u(f,e,w,y,b,_){return r(),s("div",null,[...e[0]||(e[0]=[l('<h1 id="_3-4-lesson-4-translational-motion-and-timed-control" tabindex="-1">3.4 Lesson 4: Translational Motion and Timed Control <a class="header-anchor" href="#_3-4-lesson-4-translational-motion-and-timed-control" aria-label="Permalink to &quot;3.4 Lesson 4: Translational Motion and Timed Control&quot;">​</a></h1><h2 id="_3-4-1-lesson-introduction" tabindex="-1">3.4.1 Lesson Introduction <a class="header-anchor" href="#_3-4-1-lesson-introduction" aria-label="Permalink to &quot;3.4.1 Lesson Introduction&quot;">​</a></h2><p>Building upon the programming and lighting control foundations from the previous three lessons, this lesson officially enters the core of Mecanum-wheel motion control. Taking inspiration from &quot;crab sideways movement&quot;, the concept of crab walking is introduced to explore the principles of Mecanum-wheel translation. Following the learning path of &quot;mechanical analysis → single-wheel control → encapsulated commands → timed combinations&quot;, this lesson explains how diagonal wheel speed ratios generate lateral resultant forces based on force analysis. The control method transitions from underlying four-wheel rotational speed control to encapsulated commands for timed translation. Mastering lateral movement and timed control lays a solid foundation for diagonal motion and path planning.</p><h2 id="_3-4-2-learning-objectives" tabindex="-1">3.4.2 Learning Objectives <a class="header-anchor" href="#_3-4-2-learning-objectives" aria-label="Permalink to &quot;3.4.2 Learning Objectives&quot;">​</a></h2><p><strong>1.</strong> Understand the dynamic principles of lateral translation with Mecanum wheels. Master the kinematic laws of generating resultant forces through diagonal wheel speed ratios. Learn the force analysis method of canceling vertical force components and superimposing horizontal force components.</p><p><strong>2.</strong> Independently set the individual rotational speeds and directions of the four Mecanum wheels. Master the usage of encapsulated commands for directional movement. Independently write programs for left translation, right translation, and timed combination movements.</p><p><strong>3.</strong> Establish a physical thinking framework for force component synthesis. Cultivate the ability to decompose complex movements into single-wheel controls. Develop abstract thinking from underlying principles to upper-layer encapsulation.</p><p><strong>4.</strong> Connect translational motion to narrow-aisle operation scenarios in daily life. Understand the industry value of omnidirectional movement technology in logistics warehousing and smart manufacturing. Stimulate interest in exploring mobile robotics and automation technologies.</p><h2 id="_3-4-3-preparation" tabindex="-1">3.4.3 Preparation <a class="header-anchor" href="#_3-4-3-preparation" aria-label="Permalink to &quot;3.4.3 Preparation&quot;">​</a></h2><p><strong>Hardware Preparation:</strong></p><ul><li>AiMecha M1 Mecanum-wheel robot base × 1</li><li>Type-C USB data cable × 1</li><li>Computer running Windows or macOS × 1</li></ul><p><strong>Software Preparation:</strong></p><ul><li>WonderLab graphical programming platform installed and running normally</li></ul><p><strong>Wheel Speed Parameter Description</strong>: The unit of Mecanum wheel rotational speed is revolutions per minute, abbreviated as rpm, where positive values indicate forward rotation and negative values indicate backward rotation. Setting the standard teaching demonstration rotational speed to 60 rpm is recommended for smooth movement and clear observation.</p><p><strong>Device Connection Description</strong>: Connect the mecha controller to the computer using a Type-C data cable. After successful connection, select the corresponding COM port to upload the program. The four motors on the car are pre-wired at the factory, requiring no additional wiring.</p><h2 id="_3-4-4-hands-on-project" tabindex="-1">3.4.4 Hands-On Project <a class="header-anchor" href="#_3-4-4-hands-on-project" aria-label="Permalink to &quot;3.4.4 Hands-On Project&quot;">​</a></h2><p><strong>1. Project Analysis</strong></p><p>This project focuses on the timed left and right translation of the Mecanum-wheel car, adopting a two-layer control logic consisting of a &quot;decision-making layer → an execution layer&quot;. The decision-making layer relies on sequential structures and wait commands to schedule motion states according to preset timing. The execution layer outputs four independent rotational speed signals to drive the Mecanum wheels. Car translation relies on diagonal wheel speed ratios. During left and right movement, diagonal wheels rotate in opposite directions to cancel vertical force components and superimpose horizontal force components, keeping the car body orientation unchanged. Combined with wait commands to precisely control the duration, the car completes the entire timed sequence of &quot;moving left for 5 s → stopping for 1 s → moving right for 5 s&quot;.</p><img loading="lazy" height="540" width="960" src="'+c+'" class="common_img" style="width:600px;aspect-ratio:960 / 540;"><p>💡<strong>Complete Program Preview:</strong></p><img loading="lazy" height="427" width="574" src="'+d+'" class="common_img" style="width:400px;aspect-ratio:574 / 427;"><p><strong>2. Core Commands</strong></p><table tabindex="0"><thead><tr><th style="text-align:center;">Command Category</th><th style="text-align:center;">Core Command</th><th style="text-align:left;">Functional Description</th></tr></thead><tbody><tr><td style="text-align:center;">Single-wheel control</td><td style="text-align:center;"><img loading="lazy" height="200" width="511" src="'+t+'" class="common_img" style="width:400px;aspect-ratio:511 / 200;"></td><td style="text-align:left;">Sets the rotation speed and direction of an individual wheel, where positive values indicate forward rotation and negative values indicate backward rotation.</td></tr><tr><td style="text-align:center;">Encapsulated motion</td><td style="text-align:center;"><img loading="lazy" height="321" width="551" src="'+o+'" class="common_img" style="width:400px;aspect-ratio:551 / 321;"></td><td style="text-align:left;">Encapsulated command that directly sets the car to move in eight directions at a specified speed.</td></tr><tr><td style="text-align:center;">Motion control</td><td style="text-align:center;"><img loading="lazy" height="90" width="342" src="'+a+'" class="common_img" style="width:160px;aspect-ratio:342 / 90;"></td><td style="text-align:left;">Immediately stops all motors and brakes the car in place.</td></tr></tbody></table><p><strong>3. Complete Program Description</strong></p><p><strong>Task 1: Single-Wheel Independent Control for Left and Right Translation</strong></p><ul><li><p>Use the <code>When the A key is pressed briefly</code> block as the program trigger entry.</p></li><li><p>Left translation configuration: Set the front-left wheel to -60 rpm + the front-right wheel to 60 rpm + the rear-left wheel to 60 rpm + the rear-right wheel to -60 rpm, so that diagonal counter-rotation generates a leftward resultant force.</p></li><li><p>Add a <code>wait 1 seconds</code> command to maintain the left translation state for 1 s.</p></li><li><p>Right translation configuration: Set the front-left wheel to 60 rpm + the front-right wheel to -60 rpm + the rear-left wheel to -60 rpm + the rear-right wheel to 60 rpm, so that diagonal opposite rotation generates a rightward resultant force.</p></li><li><p>Add a <code>wait 1 seconds</code> command to maintain the right translation state for 1 s.</p></li><li><p>Finally, execute the <code>Stop mecanum wheels</code> command to end the motion.</p></li></ul><img loading="lazy" height="420" width="420" src="'+p+'" class="common_img" style="width:400px;aspect-ratio:420 / 420;"><p><strong>Task 2: Encapsulated Commands to Simplify Translation Control</strong></p><ul><li><p>Use the encapsulated command <code>set Mecanum-wheel car to move in a direction at a speed of X rpm</code>.</p></li><li><p>Select from eight directions directly via the direction parameter, including move left, move right, move forward, and move backward, without manually configuring the speeds of all four wheels.</p></li><li><p>Combine with wait commands and stop commands to build a concise timed translation program.</p></li></ul><img loading="lazy" height="320" width="571" src="'+h+'" class="common_img" style="width:400px;aspect-ratio:571 / 320;"><p><strong>Task 3: Complete Timed Translation Task Moving Left for 5 s → Stopping for 1 s → Moving Right for 5 s</strong></p><ul><li><p>Program entry: When the A key is pressed briefly.</p></li><li><p>Step 1: Set the Mecanum-wheel car to move left at a speed of 60 rpm.</p></li><li><p>Step 2: Wait 5 s to maintain the left translational motion for 5 s.</p></li><li><p>Step 3: Set the Mecanum-wheel car to stop in place.</p></li><li><p>Step 4: Wait 1 s to maintain the stationary state for 1 s.</p></li><li><p>Step 5: Set the Mecanum-wheel car to move right at a speed of 60 rpm.</p></li><li><p>Step 6: Wait 5 s to maintain the right translational motion for 5 s.</p></li><li><p>Step 7: Set the Mecanum-wheel car to stop, completing the program execution.</p></li><li><p>Key parameters: The standard speed is 60 rpm, and the duration of each segment can be flexibly adjusted by modifying the wait time.</p></li></ul><img loading="lazy" height="421" width="576" src="'+m+'" class="common_img" style="width:400px;aspect-ratio:576 / 421;"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>The program source files can be downloaded from <a href="https://drive.google.com/drive/folders/1vQnjkHE58XJU_cquYayobwkfJD5ZQ1KT?usp=sharing" target="_blank" rel="noreferrer">Program Files/Timed Translation Control</a>.</strong></p></div><p><strong>Program Upload</strong>:</p><ul><li><p>Step 1: Power on the mecha controller and insert the Type-C data cable into the data port above the power switch on the controller.</p></li><li><p>Step 2: Connect the other end of the data cable to a USB port on the computer.</p></li><li><p>Step 3: Click the <strong>Connect device</strong> button at the top of the software interface and select the COM port corresponding to CH340 from the port list.</p></li><li><p>Step 4: Click the upload button in the upper-right corner to upload the compiled program to the mecha controller for execution.</p></li></ul><img loading="lazy" height="508" width="960" src="'+n+'" class="common_img" style="width:800px;aspect-ratio:960 / 508;"><h2 id="_3-4-5-expansion-and-advancement" tabindex="-1">3.4.5 Expansion and Advancement <a class="header-anchor" href="#_3-4-5-expansion-and-advancement" aria-label="Permalink to &quot;3.4.5 Expansion and Advancement&quot;">​</a></h2><p><strong>Project 1: Variable-Speed Translation Effect Experiment</strong></p><p>Design a comparative experiment by setting the translation speed to three levels: 10 rpm, 50 rpm, and 80 rpm. Observe and record the smoothness, straightness, and noise changes of the car movement at different speeds. Summarize the optimal speed range for teaching demonstrations, analyze the issues caused by excessively high or low speeds, and further understand the relationship between motor characteristics and motion performance.</p><p><strong>Project 2: Square Translation Trajectory</strong></p><p>Write a program using a combination of forward, backward, left, and right translational movements to make the car follow a square trajectory. Ensure the car moves sequentially along the four sides of the square with an identical duration for each side, eventually returning near the starting point. Comprehensively apply the four directional commands of forward, backward, left, and right along with timed control to practice arranging multi-segment motion sequences.</p><h2 id="_3-4-6-q-a" tabindex="-1">3.4.6 Q&amp;A <a class="header-anchor" href="#_3-4-6-q-a" aria-label="Permalink to &quot;3.4.6 Q&amp;A&quot;">​</a></h2><p><strong>Q1: Why is a Mecanum-wheel robot able to achieve lateral translation?</strong></p><p><strong>Answer</strong>: The core reason a Mecanum wheel achieves translation lies in its specialized wheel surface design and the principle of force component synthesis.</p><p><strong>Q2: What are the rotation directions of the four wheels during left translation and right translation?</strong></p><p><strong>Answer</strong>: The wheel speed configurations for left translation and right translation have a diagonal image relationship.</p><h2 id="_3-4-7-technical-support-and-discussion" tabindex="-1">3.4.7 Technical Support and Discussion <a class="header-anchor" href="#_3-4-7-technical-support-and-discussion" aria-label="Permalink to &quot;3.4.7 Technical Support and Discussion&quot;">​</a></h2><p>Join the forum for sharing questions, ideas, or suggestions, and answers will be provided promptly. Click the hyperlink <a href="http://forum.hiwonder.com" target="_blank" rel="noreferrer">Hiwonder Forum</a> or enter the URL in a browser: <a href="http://forum.hiwonder.com" target="_blank" rel="noreferrer">http://forum.hiwonder.com</a></p>',49)])])}const S=i(g,[["render",u]]);export{M as __pageData,S as default};
